14	    /**
15	     * Maps a city to its canonical region: Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD.
16	     *
17	     * @param city the owner's city (may be {@code null})
18	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
19	     */
20	    public static String of(String city) {
21	        if (city == null) {
22	            return "UNKNOWN";
23	        }
24	        return switch (city) {
25	            case "Sydney" -> "NSW";
26	            case "Melbourne" -> "VIC";
27	            case "Brisbane" -> "QLD";
28	            default -> "UNKNOWN";
29	        };
30	    }
31	}
