67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
74	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
78	
79	    /**
80	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
81	     * line here so audit trails can be captured independently of application logging.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.petMapper = petMapper;
100	        this.visitMapper = visitMapper;
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
121	        Owner owner = this.clinicService.findOwnerById(ownerId);
122	        if (owner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
131	        rejectMissingOrBlankFields(ownerFieldsDto);
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        owner.setAddress(normalizeAddress(owner.getAddress()));
135	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
136	        owner.setEmail(normalizeEmail(owner.getEmail()));
137	        if (owner.getRegistrationDate() == null) {
138	            owner.setRegistrationDate(LocalDate.now());
139	        }
140	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
141	        rejectDailyLimitReached(owner.getRegistrationDate());
142	        rejectCityAtCapacity(owner.getCity());
143	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
144	            assignHousehold(owner);
145	        }
146	        rejectDuplicateIdentity(owner);
147	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
148	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
149	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
171	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    /**
254	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
255	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
256	     *
257	     * @param fields the submitted owner fields
258	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
259	     *                                        {@code null} or blank, or if address is blank after
260	     *                                        normalization
261	     */
262	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
263	        List<String> missing = new ArrayList<>();
264	        if (isBlank(fields.getFirstName())) {
265	            missing.add("firstName");
266	        }
267	        if (isBlank(fields.getLastName())) {
268	            missing.add("lastName");
269	        }
270	        if (isBlank(normalizeAddress(fields.getAddress()))) {
271	            missing.add("address");
272	        }
273	        if (isBlank(fields.getCity())) {
274	            missing.add("city");
275	        }
276	        if (isBlank(fields.getTelephone())) {
277	            missing.add("telephone");
278	        }
279	        if (!missing.isEmpty()) {
280	            throw new RequiredFieldsMissingException(missing);
281	        }
282	    }
283	
284	    private boolean isBlank(String value) {
285	        return value == null || value.isBlank();
286	    }
287	
288	    /**
289	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
290	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
291	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
292	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
293	     * <p>
294	     * Where a per-country rule is defined the national-number length is validated against the country
295	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
296	     * requires exactly 10.
297	     *
298	     * @param telephone the raw telephone value from the request
299	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
300	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
301	     */
302	    private String normalizeTelephone(String telephone) {
303	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
304	        String digits;
305	        if (cleaned.startsWith("+")) {
306	            digits = cleaned.substring(1);
307	        } else {
308	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
309	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
310	            digits = "61" + national;
311	        }
312	        if (!digits.matches("[0-9]{8,15}")) {
313	            throw new InvalidTelephoneException(cleaned);
314	        }
315	        // Validate the national-number length against the country code where a rule is defined.
316	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
317	            throw new InvalidTelephoneException(cleaned);
318	        }
319	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
320	            throw new InvalidTelephoneException(cleaned);
321	        }
322	        return "+" + digits;
323	    }
324	
325	    /**
326	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
327	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
328	     * lower-cased.
329	     *
330	     * @param email the raw email value from the request, or {@code null} if omitted
331	     * @return the lower-cased email, or {@code null} if none was supplied
332	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
333	     */
334	    private String normalizeEmail(String email) {
335	        if (email == null) {
336	            return null;
337	        }
338	        String trimmed = email.strip();
339	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
340	            throw new InvalidEmailException(email);
341	        }
342	        return trimmed.toLowerCase(Locale.ROOT);
343	    }
344	
345	    /**
346	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
347	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
348	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
349	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
350	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
351	     *
352	     * @param address the raw address value from the request (may be {@code null})
353	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
354	     */
355	    private String normalizeAddress(String address) {
356	        if (address == null) {
357	            return "";
358	        }
359	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
360	        if (collapsed.isEmpty()) {
361	            return "";
362	        }
363	        String[] tokens = collapsed.split(" ");
364	        StringBuilder sb = new StringBuilder(collapsed.length());
365	        for (int i = 0; i < tokens.length; i++) {
366	            if (i > 0) {
367	                sb.append(' ');
368	            }
369	            sb.append(expandAddressAbbreviation(tokens[i]));
370	        }
371	        return sb.toString();
372	    }
373	
374	    /**
375	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
376	     * returns the token unchanged when it is not a recognised abbreviation.
377	     *
378	     * @param token an upper-cased whole-word address token
379	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
380	     */
381	    private String expandAddressAbbreviation(String token) {
382	        return switch (token) {
383	            case "ST" -> "STREET";
384	            case "RD" -> "ROAD";
385	            case "AVE" -> "AVENUE";
386	            default -> token;
387	        };
388	    }
389	
390	    /**
391	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
392	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
393	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
394	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
395	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
396	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
397	     *
398	     * @param city the owner's city
399	     * @param lastName the owner's last name
400	     * @return the assigned customer code
401	     */
402	    private String generateCustomerCode(String city, String lastName) {
403	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
404	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
405	        int sequence = (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
407	            .count() + 1;
408	        return String.format("%s-%s-%04d", city3, last3, sequence);
409	    }
410	
411	    /**
412	     * Counts how many existing owners already share the given first name and last name, compared
413	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
414	     * owner being created.
415	     *
416	     * @param firstName the first name of the owner being created
417	     * @param lastName the last name of the owner being created
418	     * @return the number of existing owners with the same first and last name (case-insensitively)
419	     */
420	    private int countNamesakes(String firstName, String lastName) {
421	        return (int) this.clinicService.findAllOwners().stream()
422	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
423	                && lastName.equalsIgnoreCase(existing.getLastName()))
424	            .count();
425	    }
426	
427	    /**
428	     * The maximum number of owners permitted in a single city. A create request whose city already
429	     * holds this many owners is rejected.
430	     */
431	    private static final int CITY_OWNER_LIMIT = 50;
432	
433	    /**
434	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
435	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
436	     * differing only in the casing of their city share one capacity pool. The count is taken before the
437	     * new owner is persisted, so it excludes the owner being created.
438	     *
439	     * @param city the city of the owner being created
440	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
441	     */
442	    private void rejectCityAtCapacity(String city) {
443	        long existing = this.clinicService.findAllOwners().stream()
444	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
445	            .count();
446	        if (existing >= CITY_OWNER_LIMIT) {
447	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
448	        }
449	    }
450	
451	    /**
452	     * The maximum number of owners permitted to be created in a single day. A create request whose
453	     * registration date already holds this many owners is rejected.
454	     */
455	    private static final int DAILY_OWNER_LIMIT = 100;
456	
457	    /**
458	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
459	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
460	     * persisted, so it excludes the owner being created.
461	     *
462	     * @param registrationDate the registration date of the owner being created
463	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
464	     */
465	    /**
466	     * Adjusts an effective registration date so that it always falls on a business day. When the given
467	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
468	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
469	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
470	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
471	     * business-day-adjusted date.
472	     *
473	     * @param date the effective registration date, supplied or defaulted
474	     * @return the same date when it is a weekday, otherwise the next Monday
475	     */
476	    private LocalDate rollToBusinessDay(LocalDate date) {
477	        DayOfWeek day = date.getDayOfWeek();
478	        if (day == DayOfWeek.SATURDAY) {
479	            return date.plusDays(2);
480	        }
481	        if (day == DayOfWeek.SUNDAY) {
482	            return date.plusDays(1);
483	        }
484	        return date;
485	    }
486	
487	    /**
488	     * The number of owners that must already exist for a given day before a further create is flagged as a
489	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
490	     * the created owner carries {@code bulkSignupWarning = true}.
491	     */
492	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
493	
494	    /**
495	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
496	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
497	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
498	     * the daily create-limit rule's accumulation path.
499	     *
500	     * @param registrationDate the registration date of the owner being created
501	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
502	     */
503	    private boolean isBulkSignupDay(LocalDate registrationDate) {
504	        long existing = this.clinicService.findAllOwners().stream()
505	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
506	            .count();
507	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
508	    }
509	
510	    private void rejectDailyLimitReached(LocalDate registrationDate) {
511	        long existing = this.clinicService.findAllOwners().stream()
512	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
513	            .count();
514	        if (existing >= DAILY_OWNER_LIMIT) {
515	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
516	        }
517	    }
518	
519	    /**
520	     * Rejects a create request whose owner collides with an existing owner on the single derived
521	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
522	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
523	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
524	     * household (same {@code householdId}) with different telephones have different keys and are both
525	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} must already
526	     * have been assigned (when {@code sharesHousehold} was requested) before this check runs, so the key
527	     * compared here is the same one that is later returned.
528	     *
529	     * @param owner the owner being created, with normalized fields and any shared {@code householdId} set
530	     * @throws DuplicateIdentityException if an existing owner has the same identity key
531	     */
532	    private void rejectDuplicateIdentity(Owner owner) {
533	        String key = identityKey(owner);
534	        boolean taken = this.clinicService.findAllOwners().stream()
535	            .anyMatch(existing -> key.equals(identityKey(existing)));
536	        if (taken) {
537	            throw new DuplicateIdentityException(key);
538	        }
539	    }
540	
541	    /**
542	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
543	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
544	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
545	     * Telephone and email are stored already normalized, so the stored values are used directly.
546	     *
547	     * @param owner the owner whose identity key is being derived
548	     * @return the owner's identity key
549	     */
550	    private String identityKey(Owner owner) {
551	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
552	        String email = owner.getEmail() == null ? "" : owner.getEmail();
553	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
554	        return telephone + "|" + email + "|" + householdId;
555	    }
556	
557	    /**
558	     * Assigns the owner being created into a shared household. When at least one existing owner has the
559	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
560	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
561	     * reused when present; otherwise a deterministic id derived from the household's last name and address
562	     * is minted, so independently created members of the same household converge on one value. When no
563	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
564	     *
565	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
566	     */
567	    private void assignHousehold(Owner owner) {
568	        String normalizedLastName = normalizeForComparison(owner.getLastName());
569	        String normalizedAddress = normalizeForComparison(owner.getAddress());
570	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
571	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
572	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
573	            .toList();
574	        if (housemates.isEmpty()) {
575	            return;
576	        }
577	        String householdId = housemates.stream()
578	            .map(Owner::getHouseholdId)
579	            .filter(id -> id != null && !id.isBlank())
580	            .findFirst()
581	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
582	        owner.setHouseholdId(householdId);
583	        for (Owner housemate : housemates) {
584	            if (!householdId.equals(housemate.getHouseholdId())) {
585	                housemate.setHouseholdId(householdId);
586	                this.clinicService.saveOwner(housemate);
587	            }
588	        }
589	    }
590	
591	    /**
592	     * Derives a stable household identifier from the normalized last name and address of a household, as
593	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
594	     * deterministic, so any owner independently joining the same household computes the same identifier.
595	     *
596	     * @param normalizedLastName the household's last name, already normalized for comparison
597	     * @param normalizedAddress the household's address, already normalized for comparison
598	     * @return a stable, shareable household identifier
599	     */
600	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
601	        String key = normalizedLastName + "|" + normalizedAddress;
602	        try {
603	            byte[] digest = MessageDigest.getInstance("SHA-256")
604	                .digest(key.getBytes(StandardCharsets.UTF_8));
605	            StringBuilder sb = new StringBuilder(digest.length * 2);
606	            for (byte b : digest) {
607	                sb.append(String.format("%02x", b));
608	            }
609	            return sb.substring(0, 16);
610	        } catch (NoSuchAlgorithmException e) {
611	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
612	        }
613	    }
614	
615	    /**
616	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
617	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
618	     * lower-cased.
619	     *
620	     * @param value the raw value to normalize (may be {@code null})
621	     * @return the normalized value, or an empty string when {@code value} is {@code null}
622	     */
623	    private String normalizeForComparison(String value) {
624	        if (value == null) {
625	            return "";
626	        }
627	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
628	    }
629	}
